;","  if (e.type === "*" && e.subtype === "*") return 1;","  return 0;","}","function selectMedia(responseContract) {","  var actual = pm.response.headers.get("Content-Type") || "";","  var content = responseContract.content || {};","  var matches = Object.keys(content).map(function (expected) { return { expected: expected, score: mediaScore(expected, actual), media: content[expected] }; }).filter(function (entry) { return entry.score > 0; }).sort(function (a, b) { return b.score - a.score; });","  if (matches.length === 0) return { error: "Content-Type " + actual + " does not match OpenAPI content for " + contract.method + " " + contract.path + " status " + pm.response.code + "; expected " + Object.keys(content).join(", ") };","  if (matches.length > 1 && matches[0].score === matches[1].score) return { error: "Content-Type " + actual + " ambiguously matches OpenAPI content for " + contract.method + " " + contract.path + " status " + pm.response.code + "; expected " + Object.keys(content).join(", ") };","  return matches[0];","}","var selected = selectedResponseContract();","var bodyExpectation = selectedBodyExpectation();","pm.test('OpenAPI operation mapping exists', function () { pm.expect(contract.path).to.be.a('string').and.not.empty; });","pm.test('Status code is defined by OpenAPI', function () { pm.expect(selected, 'No OpenAPI response defined for ' + contract.method + ' ' + contract.path + ' status ' + pm.response.code).to.exist; });","pm.test('Response headers match OpenAPI', function () {","  if (!selected) return;","  var headers = selected.value.headers || [];","  headers.forEach(function (header) {","    var actual = pm.response.headers.get(header.name);","    if (!actual && header.required) pm.expect.fail("OpenAPI response header missing for " + contract.method + " " + contract.path + ": " + header.name);","    if (!actual) return;","    if (header.unsupported) pm.expect.fail("OpenAPI response header unsupported for " + contract.method + " " + contract